// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: sender and amount to deposit
    function testFuzz_property(address sender, uint256 amount) public {
        // keep sender usable and amount within reasonable bounds but allow full range
        vm.assume(sender != address(0));

        // ensure sender has funds to send the deposit
        uint256 fund = bound(amount, 1, type(uint256).max);
        // cap the funding for practicality in the test environment
        uint256 supply = bound(fund, 1, 1 ether);
        vm.deal(sender, supply);

        // read the initial count
        uint256 before = c.depositsCount();

        // perform the payable call to receive() from sender
        vm.prank(sender);
        // send at least 1 wei (we ensure supply >= 1 above)
        c.call{value: 1}("");

        // single assertion: after a successful deposit, depositsCount increased by exactly 1
        uint256 after = c.depositsCount();
        assertTrue(after == before + 1);
    }
}

