pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the depositor address and the amount to send
    function testFuzz_property(address depositor, uint256 amount) public {
        // admissible domain: depositor is not zero and amount fits an address balance setup
        vm.assume(depositor != address(0));
        // bound amount to a reasonable range including zero and large values
        amount = bound(amount, 0, type(uint256).max);

        // capture before count
        uint256 before = c.depositsCount();

        // fund depositor and perform the payable receive call as that depositor
        vm.deal(depositor, amount);
        vm.prank(depositor);
        // perform low-level send of ETH to trigger receive()
        // wrap in try/catch to observe success vs revert
        bool ok;
        try c.call{value: amount}("") returns (bytes memory) {
            ok = true;
        } catch {
            ok = false;
        }

        // After a successful receive (ok == true), depositsCount must have increased by exactly 1
        // We assert the universal property: if the call succeeded then depositsCount == before + 1
        // single assertion reading c
        assertTrue(!ok || c.depositsCount() == before + 1);
    }
}

