pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the sender and amount. The distinguishing case is when depositsCount == type(uint).max and a nonzero amount is sent.
    function testFuzz_property(address sender, uint256 amount) public {
        // keep sender nonzero to be a proper actor
        vm.assume(sender != address(0));
        // bound amount to a wide range but allow zero too
        amount = bound(amount, 0, type(uint256).max);

        // Ensure sender has ETH to send
        vm.deal(sender, amount);

        // record before
        uint256 before = c.depositsCount();

        // perform the payable call as the sender to trigger receive()
        bool ok;
        vm.prank(sender);
        (bool success, ) = address(c).call{value: amount}("");
        ok = success;

        // The reference contract: for any successful call, depositsCount increments by exactly 1.
        // We assert a general property that the reference satisfies for all inputs: if the receive call succeeded,
        // then c.depositsCount == before + (success ? 1 : 0).
        // This single assert reads c's public getter.
        if (ok) {
            assertTrue(c.depositsCount() == before + 1);
        } else {
            // if the call failed, then depositsCount must be unchanged
            assertTrue(c.depositsCount() == before);
        }
    }
}

