pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: sender (address) and amount (uint256)
    function testFuzz_property(address sender, uint256 amount) public {
        // Keep domain wide but make amount small enough to fund and nonzero to exercise payable path
        vm.assume(sender != address(0));
        amount = bound(amount, 0, 1 ether);

        // Deploy a helper that will accept the payment but revert when called by C via sendMoney/call.
        Reverter rev = new Reverter();

        // Fund the sender so it can send ETH
        vm.deal(sender, amount);

        // Record depositsCount before
        uint before = c.depositsCount();

        // Make the call to receive by sending value from sender
        vm.prank(sender);
        // If amount==0, this still triggers receive if payable with 0 value
        // Use low-level call to ensure receive is exercised
        (bool sent,) = address(c).call{value: amount}("");
        // The reference guarantees that for any successful call (sent==true), depositsCount increased by exactly 1
        if (sent) {
            uint after = c.depositsCount();
            // single assertion: reference property that must hold for all inputs; mutant will violate for some inputs
            assertTrue(after == before + 1);
        } else {
            // If the call failed (should be rare), still the reference would not increment; assert that count unchanged
            uint after = c.depositsCount();
            assertTrue(after == before);
        }

        // Now exercise interaction where C will call an external address that reverts: sendMoney should perform a low-level call
        // Give C some balance to forward
        vm.deal(address(c), 1 wei);

        // From owner (setUp deployer) call sendMoney targeting the reverting contract with some value
        vm.prank(address(this));
        // This call should not affect depositsCount in the reference beyond normal behavior; record before
        uint before2 = c.depositsCount();
        // call sendMoney which does an unchecked low-level call to the target; target will revert
        c.sendMoney(address(rev), 1 wei, "");
        uint after2 = c.depositsCount();
        // The reference's rule: each successful receive invocation increments by exactly 1 and external failing calls do not produce extra increments
        assertTrue(after2 == before2);
    }
}

contract Reverter {
    fallback() external payable {
        revert("nope");
    }
    receive() external payable {
        revert("nope");
    }
}

