pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: amount to send and whether the external callee will revert (as a selector via bool)
    function testFuzz_property(uint128 amount, bool doRevert) public {
        // keep amount wide but not exceeding available test balance
        uint256 sendAmount = bound(amount, 0, 1 ether);

        // deploy a helper that will act as the target of C.sendMoney when owner calls it
        AttackerHelper helper = new AttackerHelper(doRevert);

        // fund the helper so any calls to it have balance if needed (not required but harmless)
        vm.deal(address(this), 2 ether);

        // set up an external actor that will send ETH to c (a distinct EOA)
        address payer = address(0xBEEF);
        vm.deal(payer, 2 ether);

        // record depositsCount before
        uint256 before = c.depositsCount();

        // make the payer send Ether to c via receive()
        vm.prank(payer);
        (bool ok, ) = address(c).call{value: sendAmount}("");
        // require the call itself succeeded (we are testing successful invocation path)
        // if call reverted, then reference did not execute receive; we only assert when it executed
        if (!ok) return;

        // Now, to exercise potential interactions that differentiate implementations, have the owner invoke sendMoney
        // which performs a low-level call to an external target. The mutant's missing require can cause depositsCount
        // discrepancies correlated with failing external interactions; we fuzzed doRevert to toggle that.
        // Owner is msg.sender at contract creation (setUp), which is this test contract.
        // Ensure owner has funds to trigger potential effects.
        vm.deal(address(this), 2 ether);

        // call sendMoney to the helper which may revert or not on being called
        c.sendMoney(address(helper), 0, "");

        // exactly one assertion: in the correct contract, after a successful receive invocation depositsCount == before + 1
        // This reads c's public getter; the buggy mutant (which increments unconditionally) will be broken for some doRevert inputs
        uint256 after = c.depositsCount();
        assertTrue(after == before + 1);
    }
}

// Helper that can be toggled to revert on fallback to simulate a failing external callee
contract AttackerHelper {
    bool public shouldRevert;
    constructor(bool _r) payable {
        shouldRevert = _r;
    }
    fallback() external payable {
        if (shouldRevert) revert("revert from helper");
    }
}

