contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameter: amount to send in wei (must be >0 to hit payable branch) and an initial top-up count manipulator
    function testFuzz_property(uint256 sendAmount, uint256 prepCalls) public {
        // Keep domains wide but meaningful
        // ensure sendAmount fits into uint128 to avoid absurd VM issues, but allow zero as well
        sendAmount = bound(sendAmount, 0, type(uint128).max);
        // prepCalls controls how many times we pre-invoke receive to raise depositsCount; keep it bounded but allow large values
        prepCalls = bound(prepCalls, 0, 300);

        // Fund an externally owned account to act as sender
        address sender = address(0xBEEF);
        vm.deal(sender, sendAmount + 1 ether);

        // Bring depositsCount closer to potential overflow by calling receive multiple times legitimately
        // We must call receive via sending ether from 'sender' to c
        for (uint256 i = 0; i < prepCalls; ++i) {
            vm.prank(sender);
            // send 1 wei each preparatory time (safe small amount)
            (bool ok, ) = address(c).call{value: 1 wei}("");
            require(ok);
        }

        // record previous depositsCount via getter
        uint256 before = c.depositsCount();

        // Now perform the fuzzed payment: send `sendAmount` wei from sender
        vm.prank(sender);
        (bool ok2, ) = address(c).call{value: sendAmount}("");
        // the call may succeed or fail; we only observe state after it

        uint256 after = c.depositsCount();

        // GENERAL RULE (single assertion): after >= before
        // The reference C enforces require((before + 1) >= before) so a successful receive cannot produce a smaller value;
        // the mutant removing the require can allow wrapping/invalid increments so after < before for some inputs.
        assertTrue(after >= before);
    }
}

