pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the sender and the amount; the property: a successful payable call to receive increases depositsCount.
    function testFuzz_property(address sender, uint256 amount) public {
        // keep amount in a reasonable domain but wide: allow zero and non-zero;
        // we will only proceed when sender has funds and amount fits into balance.
        vm.assume(sender != address(0));
        // bound amount so vm.deal can accept it reasonably (avoid absurd huge values)
        amount = bound(amount, 0, 1 ether);

        // fund the sender so the call can send value
        vm.deal(sender, amount);

        uint256 before = c.depositsCount();

        bool ok;
        // perform the external payable call to receive via a plain low-level send (prank to set msg.sender)
        vm.prank(sender);
        try c.call{value: amount}() {
            // This branch is unreachable because c.call isn't an actual typed call; use try/catch pattern for receive
            ok = true;
        } catch {
            ok = false;
        }

        // The above try/catch can't call receive via c.call in typed fashion; instead perform the direct transfer by invoking payable fallback through a simple address payable call.
        // We'll do it concretely: perform the transfer and catch whether it reverts using try/catch on a helper that forwards.

        // Deploy a small helper that performs a low-level call to c with value; this allows catching revert outcome.
        Forwarder f = new Forwarder();
        vm.deal(address(f), 0);

        // Fund the forwarder from the fuzzer-provided sender so it can forward value
        if (amount > 0) {
            vm.prank(sender);
            (bool sent,) = address(f).call{value: amount}("");
            // fund forwarder directly by having sender send to it; require success else skip
            if (!sent) {
                // cannot fund forwarder: treat as failure
            }
        }

        // Now forwarder will call c with value and we can observe success via try/catch
        try f.forward{gas: gasleft()}(payable(address(c)), amount) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        uint256 after = c.depositsCount();

        // General rule to assert: if the low-level receive call succeeded (ok == true), then depositsCount increased by 1.
        // We express this as a single assertTrue reading c: either the call failed (ok == false) OR depositsCount == before + 1.
        // Because assertTrue must read c's public surface, we observe depositsCount and encode the implication.
        // Build the condition: ok == false || after == before + 1
        bool condition = (!ok) || (after == before + 1);
        assertTrue(condition);
    }
}

// Helper that forwards value to target and returns whether the call succeeded.
contract Forwarder {
    // receive so it can accept funds
    receive() external payable {}

    function forward(address payable target, uint256 value) public returns (bool) {
        (bool success,) = target.call{value: value}("");
        if (!success) revert();
        return success;
    }
}

