        // This excludes counterexamples where msg.sender differs or where owner already equals caller in the target contract state.
        require(msg.sender == caller && c.owner() == caller);

        bool reverted;
        try c.withdraw(amount) { reverted = false; } catch { reverted = true; }

        // The original contract onlyOwner on withdraw causes any non-owner caller to revert.
        // Assert: if caller is not the owner (observed via c.owner()), then the withdraw call must have reverted.
        assert((c.owner() != caller) ? reverted : true);
    }
    receive() external payable { }
}

